def folded(items: Iterable[tuple[str, str]]) -> dict[str, str]:
    out: dict[str, tuple[str, str]] = {}
    for name, value in items:
        out.pop(name.lower(), None)
        out[name.lower()] = (name, value)
    return dict(out.values())


def shaped(value: object, shape: str | None) -> bool:
    kinds = SHAPES.get(shape or "", (object,))
    return isinstance(value, kinds) and not (
        shape == "number" and isinstance(value, bool)
    )


def scalar(name: str, value: str, kind: str) -> object:
    if kind == "boolean" and value in ("true", "false"):
        return value == "true"
    try:
        return {"integer": int, "number": float, "string": str}[kind](value)
    except (KeyError, ValueError):
        raise DecodeError(f"the {name} header is not a valid {kind}") from None


